 viewBinding.miniPlayerPanel.root.isVisible = true
 viewBinding.miniPlayerPanel.tvTitleMiniPlayer.text = item?.title
 viewBinding.miniPlayerPanel.tvSingerMiniPlayer.text = item?.singer
 }
}
